#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PreparedSandbox {
    pub entrypoint: SandboxEntrypoint,
    pub session: SandboxSession,
    pub root: PathBuf,
    pub input: PathBuf,
    pub output: PathBuf,
    pub tools: PathBuf,
    pub config: PathBuf,
    pub manifest: PathBuf,
    pub input_files: Vec<SandboxArtifact>,
    pub tool_files: Vec<SandboxArtifact>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SandboxSpec {
    pub entrypoint: SandboxEntrypoint,
    pub session: SandboxSession,
    pub root: PathBuf,
    pub inputs: Vec<SandboxFileTransfer>,
    pub tools: Vec<SandboxFileTransfer>,
    #[serde(default)]
    pub mappings: Vec<SandboxMapping>,
    pub runtime_config: Option<WindowsRuntimeConfig>,
}

pub fn prepare(spec: &SandboxSpec) -> Result<PreparedSandbox> {
    spec.session.validate()?;
    let runtime_config = match (&spec.entrypoint, &spec.runtime_config) {
        (SandboxEntrypoint::BoundaryProbe, None) => None,
        (SandboxEntrypoint::OriginalPe, Some(config)) => {
            config.validate()?;
            ensure!(
                matches!(
                    config.adapter,
                    WindowsRuntimeAdapter::OriginalPe32 | WindowsRuntimeAdapter::OriginalPe64
                ),
                "the original PE entrypoint requires a PE adapter"
            );
            ensure!(
                matches!(&config.entry, WindowsRuntimeEntry::CommandLine { .. }),
                "the original PE entrypoint requires a command-line entry"
            );
            if let WindowsRuntimeEntry::CommandLine { path, .. } = &config.entry {
                ensure!(
                    path == &config.target_path,
                    "the original PE entry must execute the declared target"
                );
            }
            ensure!(
                config.fingerprint()? == spec.session.config_sha256,
                "the sandbox session and runtime configuration hashes disagree"
            );
            Some(config)
        }
        (SandboxEntrypoint::BoundaryProbe, Some(_)) => {
            return Err(anyhow::anyhow!(
                "the boundary probe does not accept a runtime configuration"
            ));
        }
        (SandboxEntrypoint::OriginalPe, None) => {
            return Err(anyhow::anyhow!(
                "the original PE entrypoint requires a runtime configuration"
            ));
        }
        (SandboxEntrypoint::WindowsPython, Some(config)) => {
            config.validate()?;
            ensure!(
                config.adapter == WindowsRuntimeAdapter::PythonCall,
                "the Windows Python entrypoint requires the Python adapter"
            );
            ensure!(
                matches!(&config.entry, WindowsRuntimeEntry::Function { .. }),
                "the Windows Python entrypoint requires a function entry"
            );
            ensure!(
                config.fingerprint()? == spec.session.config_sha256,
                "the sandbox session and runtime configuration hashes disagree"
            );
            ensure!(
                spec.mappings.iter().any(|mapping| {
                    mapping.guest == GUEST_PYTHON
                        && mapping.read_only
                        && mapping.host.join("python.exe").is_file()
                }),
                "the Windows Python entrypoint requires a read-only Python runtime mapping"
            );
            Some(config)
        }
        (SandboxEntrypoint::WindowsPython, None) => {
            return Err(anyhow::anyhow!(
                "the Windows Python entrypoint requires a runtime configuration"
            ));
        }
        (SandboxEntrypoint::WindowsNativeSource, Some(config)) => {
            config.validate()?;
            ensure!(
                config.adapter == WindowsRuntimeAdapter::NativeSource,
                "the native-source entrypoint requires the native-source adapter"
            );
            ensure!(
                matches!(&config.entry, WindowsRuntimeEntry::CommandLine { .. }),
                "the native-source entrypoint requires a command-line entry"
            );
            if let WindowsRuntimeEntry::CommandLine { path, .. } = &config.entry {
                ensure!(
                    path == &config.target_path,
                    "the native-source entry must execute the declared target"
                );
            }
            ensure!(
                config.fingerprint()? == spec.session.config_sha256,
                "the sandbox session and runtime configuration hashes disagree"
            );
            ensure!(
                spec.mappings.iter().any(|mapping| {
                    mapping.guest == GUEST_ZIG
                        && mapping.read_only
                        && mapping.host.join("zig.exe").is_file()
                }),
                "the native-source entrypoint requires a read-only Zig runtime mapping"
            );
            Some(config)
        }
        (SandboxEntrypoint::WindowsNativeSource, None) => {
            return Err(anyhow::anyhow!(
                "the native-source entrypoint requires a runtime configuration"
            ));
        }
        (SandboxEntrypoint::TinyInstPe, Some(config)) => {
            config.validate()?;
            ensure!(
                matches!(
                    config.adapter,
                    WindowsRuntimeAdapter::OriginalPe32 | WindowsRuntimeAdapter::OriginalPe64
                ),
                "the TinyInst entrypoint requires a PE adapter"
            );
            ensure!(
                matches!(&config.entry, WindowsRuntimeEntry::CommandLine { .. }),
                "the TinyInst entrypoint requires a command-line entry"
            );
            if let WindowsRuntimeEntry::CommandLine { path, .. } = &config.entry {
                ensure!(
                    path == &config.target_path,
                    "the TinyInst entry must execute the declared target"
                );
            }
            ensure!(
                config.fingerprint()? == spec.session.config_sha256,
                "the sandbox session and runtime configuration hashes disagree"
            );
            ensure!(
                spec.mappings.iter().any(|mapping| {
                    mapping.guest == GUEST_TINYINST
                        && mapping.read_only
                        && mapping.host.join("litecov.exe").is_file()
                }),
                "the TinyInst entrypoint requires a read-only TinyInst runtime mapping"
            );
            Some(config)
        }
        (SandboxEntrypoint::TinyInstPe, None) => {
            return Err(anyhow::anyhow!(
                "the TinyInst entrypoint requires a runtime configuration"
            ));
        }
        (SandboxEntrypoint::LibFuzzerPrebuilt, Some(config)) => {
            config.validate()?;
            ensure!(
                config.mode == WindowsRuntimeMode::Fuzz,
                "the libFuzzer entrypoint requires FUZZ mode"
            );
            ensure!(
                config.adapter == WindowsRuntimeAdapter::LibFuzzerPrebuilt,
                "the libFuzzer entrypoint requires the prebuilt libFuzzer adapter"
            );
            ensure!(
                config.fingerprint()? == spec.session.config_sha256,
                "the sandbox session and runtime configuration hashes disagree"
            );
            ensure!(
                spec.mappings.iter().any(|mapping| {
                    mapping.guest == GUEST_LLVM
                        && mapping.read_only
                        && mapping.host.join("bin/clang.exe").is_file()
                }),
                "the libFuzzer entrypoint requires a read-only LLVM runtime mapping"
            );
            Some(config)
        }
        (SandboxEntrypoint::LibFuzzerPrebuilt, None) => {
            return Err(anyhow::anyhow!(
                "the libFuzzer entrypoint requires a runtime configuration"
            ));
        }
    };
    for mapping in &spec.mappings {
        ensure!(
            mapping.host.is_absolute() && mapping.host.is_dir() && !is_reparse_point(&mapping.host),
            "sandbox mapping host must be an absolute directory"
        );
        ensure!(
            (mapping.guest == GUEST_PYTHON
                || mapping.guest == GUEST_ZIG
                || mapping.guest == GUEST_TINYINST
                || mapping.guest == GUEST_LLVM)
                && mapping.read_only,
            "only fixed read-only Python, Zig, TinyInst, and LLVM mappings are currently supported"
        );
        ensure!(
            mapping.host != spec.root.join("input")
                && mapping.host != spec.root.join("output")
                && mapping.host != spec.root.join("tools"),
            "runtime mapping may not overlap attempt directories"
        );
    }
    ensure!(
        spec.inputs.len() <= 256 && spec.tools.len() <= 128,
        "a sandbox attempt may import at most 256 inputs and 128 tools"
    );
    if spec.root.exists() {
        ensure!(spec.root.is_dir(), "sandbox root is not a directory");
        ensure!(
            fs::read_dir(&spec.root)?.next().is_none(),
            "sandbox root must be empty so outputs cannot belong to an older attempt"
        );
    } else {
        fs::create_dir_all(&spec.root)?;
    }
    ensure!(
        !is_reparse_point(&spec.root),
        "sandbox root may not be a reparse point"
    );
    let input = spec.root.join("input");
    let output = spec.root.join("output");
    let tools = spec.root.join("tools");
    for directory in [&input, &output, &tools] {
        fs::create_dir(directory)?;
        ensure!(
            !is_reparse_point(directory),
            "sandbox directory may not be a reparse point"
        );
    }

    let input_files = import_files(&spec.inputs, &input)?;
    let tool_files = import_files(&spec.tools, &tools)?;
    ensure!(
        tool_files
            .iter()
            .any(|item| item.path == spec.entrypoint.guest_script()),
        "the sandbox tool set is missing its fixed entrypoint"
    );
    write_json(
        &input.join(RECEIPT_FILE),
        &json!({
            "schema_version": SANDBOX_SCHEMA_VERSION,
            "run_id": spec.session.run_id,
            "attempt_id": spec.session.attempt_id,
            "session_id": spec.session.session_id,
            "target_sha256": spec.session.target_sha256,
            "config_sha256": spec.session.config_sha256
        }),
    )?;
    let receipt_artifact = artifact(&input.join(RECEIPT_FILE), RECEIPT_FILE)?;
    let input_files = merge_artifacts(input_files, receipt_artifact);
    let input_files = if let Some(runtime_config) = runtime_config {
        let runtime_path = input.join("runtime-config.json");
        write_json(&runtime_path, &serde_json::to_value(runtime_config)?)?;
        let runtime_artifact = artifact(&runtime_path, "runtime-config.json")?;
        merge_artifacts(input_files, runtime_artifact)
    } else {
        input_files
    };
    ensure!(
        input_files
            .iter()
            .any(|item| item.sha256 == spec.session.target_sha256),
        "the imported input set must contain the declared target hash"
    );
    if let Some(runtime_config) = runtime_config {
        ensure!(
            input_files
                .iter()
                .any(|item| item.path == runtime_config.target_path
                    && item.sha256 == runtime_config.target_sha256),
            "the imported input set must contain the declared runtime target"
        );
    }

    let manifest = spec.root.join("host-manifest.json");
    write_json(
        &manifest,
        &json!({
            "schema_version": SANDBOX_SCHEMA_VERSION,
            "session": spec.session,
            "guest_paths": {
                "tools": GUEST_TOOLS,
                "input": GUEST_INPUT,
                "output": GUEST_OUTPUT
            },
            "policy": {
                "networking": "DISABLED",
                "v_gpu": "DISABLED",
                "clipboard_redirection": "DISABLED",
                "printer_redirection": "DISABLED",
                "audio_input_redirection": "DISABLED",
                "video_input_redirection": "DISABLED",
                "protected_client": "ENABLED",
                "memory_mb": spec.session.memory_mb,
                "input_read_only": true,
                "output_read_only": false
            },
            "input_files": input_files,
            "tool_files": tool_files,
            "entrypoint": spec.entrypoint,
            "mappings": spec.mappings
        }),
    )?;
    let config = spec.root.join("sandbox.wsb");
    fs::write(
        &config,
        sandbox_config(
            &tools,
            &input,
            &output,
            spec.session.memory_mb,
            spec.entrypoint,
            &spec.mappings,
        )?,
    )?;
    Ok(PreparedSandbox {
        entrypoint: spec.entrypoint,
        session: spec.session.clone(),
        root: spec.root.clone(),
        input,
        output,
        tools,
        config,
        manifest,
        input_files,
        tool_files,
    })
}

pub fn verify_inputs(prepared: &PreparedSandbox) -> Result<()> {
    for (base, expected) in prepared
        .input_files
        .iter()
        .map(|expected| (&prepared.input, expected))
        .chain(
            prepared
                .tool_files
                .iter()
                .map(|expected| (&prepared.tools, expected)),
        )
    {
        let path = base.join(&expected.path);
        ensure!(
            path.is_file(),
            "sandbox input is missing: {}",
            expected.path
        );
        ensure!(!is_reparse_point(&path), "sandbox input is a reparse point");
        let actual = artifact(&path, &expected.path)?;
        ensure!(
            actual == *expected,
            "sandbox input changed after preparation: {}",
            expected.path
        );
    }
    Ok(())
}

pub fn collect_output(
    prepared: &PreparedSandbox,
    policy: &SandboxOutputPolicy,
) -> Result<SandboxOutput> {
    policy.validate()?;
    ensure!(
        prepared.output.is_dir() && !is_reparse_point(&prepared.output),
        "sandbox output directory is missing or unsafe"
    );
    let mut artifacts = Vec::new();
    let mut total_bytes = 0u64;
    for entry in fs::read_dir(&prepared.output)? {
        let entry = entry?;
        let path = entry.path();
        ensure!(path.is_file(), "sandbox output must contain files only");
        ensure!(
            !is_reparse_point(&path),
            "sandbox output is a reparse point"
        );
        let relative = path
            .strip_prefix(&prepared.output)
            .map_err(|_| anyhow::anyhow!("output path escapes its directory"))?
            .to_string_lossy()
            .replace('\\', "/");
        ensure!(
            policy.allowed(&relative),
            "sandbox output is not allowed by the export policy: {relative}"
        );
        let artifact = artifact(&path, &relative)?;
        ensure!(
            artifact.size <= policy.max_file_bytes,
            "sandbox output exceeds the per-file limit: {relative}"
        );
        total_bytes = total_bytes
            .checked_add(artifact.size)
            .ok_or_else(|| anyhow::anyhow!("sandbox output size overflow"))?;
        artifacts.push(artifact);
    }
    ensure!(
        total_bytes <= policy.max_total_bytes,
        "sandbox output exceeds the total size limit"
    );
    let actual: BTreeSet<_> = artifacts.iter().map(|item| item.path.as_str()).collect();
    for required in &policy.required_files {
        ensure!(
            actual.contains(required.as_str()),
            "required sandbox output is missing: {required}"
        );
    }
    let receipt_path = prepared.output.join(RECEIPT_FILE);
    let receipt_text = fs::read_to_string(&receipt_path)
        .with_context(|| format!("cannot read sandbox receipt {receipt_path:?}"))?;
    let receipt: SandboxReceipt = serde_json::from_str(receipt_text.trim_start_matches('\u{feff}'))
        .with_context(|| format!("invalid sandbox receipt {receipt_path:?}"))?;
    receipt.validate(&prepared.session)?;
    artifacts.sort_by(|left, right| left.path.cmp(&right.path));
    Ok(SandboxOutput {
        receipt,
        artifacts,
        total_bytes,
    })
}

pub async fn run_probe(
    prepared: &PreparedSandbox,
    timeout: Duration,
    cancel: CancellationToken,
) -> Result<SandboxExecution> {
    ensure!(
        prepared.entrypoint == SandboxEntrypoint::BoundaryProbe,
        "run_probe is only for the harmless boundary probe"
    );
    run_sandbox(prepared, timeout, cancel).await
}

pub async fn run_original_pe(
    prepared: &PreparedSandbox,
    timeout: Duration,
    cancel: CancellationToken,
) -> Result<SandboxExecution> {
    ensure!(
        prepared.entrypoint == SandboxEntrypoint::OriginalPe,
        "run_original_pe is only for declared original PE attempts"
    );
    run_sandbox(prepared, timeout, cancel).await
}

