async fn run_sandbox(
    prepared: &PreparedSandbox,
    timeout: Duration,
    cancel: CancellationToken,
) -> Result<SandboxExecution> {
    let system_root = std::env::var_os("SystemRoot")
        .map(PathBuf::from)
        .unwrap_or_else(|| r"C:\Windows".into());
    let sandbox = system_root.join(r"System32\WindowsSandbox.exe");
    ensure!(sandbox.is_file(), "Windows Sandbox executable is missing");

    let stdout = fs::File::create(prepared.root.join("sandbox.stdout.log"))?;
    let stderr = fs::File::create(prepared.root.join("sandbox.stderr.log"))?;
    let mut launcher = Command::new(&sandbox)
        .arg(&prepared.config)
        .stdout(Stdio::from(stdout))
        .stderr(Stdio::from(stderr))
        .kill_on_drop(true)
        .spawn()?;
    let mut launcher_exit_code = None;
    if let Ok(status) = time::timeout(Duration::from_secs(10), launcher.wait()).await {
        launcher_exit_code = status?.code();
    }

    let started_at = std::time::Instant::now();
    let mut remote_ids = BTreeSet::new();
    while started_at.elapsed() < timeout && !cancel.is_cancelled() {
        remote_ids = matching_remote_sessions_with_retry(&prepared.config, &prepared.root).await?;
        if !remote_ids.is_empty() {
            break;
        }
        time::sleep(Duration::from_secs(1)).await;
    }
    let remote_session_started = !remote_ids.is_empty();

    let mut timed_out = false;
    while remote_session_started && !remote_ids.is_empty() && !cancel.is_cancelled() {
        if started_at.elapsed() >= timeout {
            timed_out = true;
            break;
        }
        time::sleep(Duration::from_secs(5)).await;
        remote_ids = matching_remote_sessions_with_retry(&prepared.config, &prepared.root).await?;
    }
    let cancelled = cancel.is_cancelled();
    let mut cleanup_output = String::new();
    if !remote_ids.is_empty() && (cancelled || timed_out) {
        cleanup_output = terminate_remote_sessions(&remote_ids, &prepared.root).await?;
        remote_ids = matching_remote_sessions_with_retry(&prepared.config, &prepared.root).await?;
    }

    if launcher_exit_code.is_none() {
        launcher_exit_code = match time::timeout(Duration::from_secs(30), launcher.wait()).await {
            Ok(status) => status?.code(),
            Err(_) => {
                launcher.kill().await?;
                launcher.wait().await?.code()
            }
        };
    }
    let remote_session_closed = remote_ids.is_empty()
        && matching_remote_sessions_with_retry(&prepared.config, &prepared.root)
            .await?
            .is_empty();
    let success = remote_session_started
        && remote_session_closed
        && !timed_out
        && !cancelled
        && launcher_exit_code == Some(0);
    Ok(SandboxExecution {
        launcher_exit_code,
        remote_session_started,
        remote_session_closed,
        timed_out,
        cancelled,
        cleanup_output,
        success,
    })
}

async fn matching_remote_sessions(config: &Path, directory: &Path) -> Result<BTreeSet<u32>> {
    let system_root = std::env::var_os("SystemRoot").unwrap_or_default();
    let powershell =
        Path::new(&system_root).join(r"System32\WindowsPowerShell\v1.0\powershell.exe");
    let script = r#"$config = $env:AEGIS_SANDBOX_CONFIG; Get-CimInstance Win32_Process -Filter "Name = 'WindowsSandboxRemoteSession.exe'" | Where-Object { $_.CommandLine -and $_.CommandLine.Contains($config) } | ForEach-Object { $_.ProcessId }"#;
    let mut env = BTreeMap::new();
    env.insert(
        "AEGIS_SANDBOX_CONFIG".into(),
        config.to_string_lossy().into_owned(),
    );
    let output = crate::process::run(
        crate::process::ProcessSpec {
            program: powershell,
            args: vec![
                "-NoProfile".into(),
                "-NonInteractive".into(),
                "-Command".into(),
                script.into(),
            ],
            directory: directory.into(),
            env,
            timeout: Duration::from_secs(30),
        },
        CancellationToken::new(),
        |_| {},
    )
    .await?;
    ensure!(
        output.exit_code == Some(0) && !output.cancelled && !output.timed_out,
        "cannot query the Windows Sandbox remote session"
    );
    let mut ids = BTreeSet::new();
    for line in String::from_utf8_lossy(&output.stdout).lines() {
        if let Ok(id) = line.trim().parse::<u32>() {
            ids.insert(id);
        }
    }
    Ok(ids)
}

async fn matching_remote_sessions_with_retry(
    config: &Path,
    directory: &Path,
) -> Result<BTreeSet<u32>> {
    let mut last_error = None;
    for attempt in 0..3 {
        match matching_remote_sessions(config, directory).await {
            Ok(ids) => return Ok(ids),
            Err(error) if attempt < 2 => {
                last_error = Some(error);
                time::sleep(Duration::from_secs(2)).await;
            }
            Err(error) => return Err(error),
        }
    }
    Err(last_error.unwrap_or_else(|| anyhow::anyhow!("sandbox process query failed")))
}

async fn terminate_remote_sessions(ids: &BTreeSet<u32>, directory: &Path) -> Result<String> {
    let system_root = std::env::var_os("SystemRoot").unwrap_or_default();
    let taskkill = Path::new(&system_root).join(r"System32\taskkill.exe");
    let mut output = String::new();
    for id in ids {
        let result = crate::process::run(
            crate::process::ProcessSpec {
                program: taskkill.clone(),
                args: vec!["/PID".into(), id.to_string(), "/T".into(), "/F".into()],
                directory: directory.into(),
                env: BTreeMap::new(),
                timeout: Duration::from_secs(20),
            },
            CancellationToken::new(),
            |_| {},
        )
        .await?;
        output.push_str(&String::from_utf8_lossy(&result.stdout));
        output.push_str(&String::from_utf8_lossy(&result.stderr));
    }
    Ok(output.trim().into())
}

fn import_files(
    transfers: &[SandboxFileTransfer],
    destination_root: &Path,
) -> Result<Vec<SandboxArtifact>> {
    let mut artifacts = Vec::new();
    let mut seen = BTreeSet::new();
    for transfer in transfers {
        let relative = relative_path(&transfer.path)
            .with_context(|| format!("unsafe sandbox import path: {}", transfer.path))?;
        ensure!(
            seen.insert(relative.to_owned()),
            "duplicate sandbox import path"
        );
        let source = &transfer.source;
        ensure!(source.is_file(), "sandbox import is not a file: {source:?}");
        ensure!(
            !is_reparse_point(source),
            "sandbox import is a reparse point"
        );
        let destination = destination_root.join(relative);
        if let Some(parent) = destination.parent() {
            fs::create_dir_all(parent)?;
        }
        ensure!(
            !destination.exists(),
            "sandbox import destination already exists: {}",
            transfer.path
        );
        fs::copy(source, &destination)
            .with_context(|| format!("cannot copy sandbox file {}", transfer.path))?;
        artifacts.push(artifact(&destination, relative)?);
    }
    Ok(artifacts)
}

fn merge_artifacts(
    mut values: Vec<SandboxArtifact>,
    additional: SandboxArtifact,
) -> Vec<SandboxArtifact> {
    values.push(additional);
    values.sort_by(|left, right| left.path.cmp(&right.path));
    values
}

fn artifact(path: &Path, relative: &str) -> Result<SandboxArtifact> {
    let data = fs::read(path).with_context(|| format!("cannot read sandbox file {path:?}"))?;
    Ok(SandboxArtifact {
        path: relative.into(),
        sha256: aegis_domain::sha256(&data),
        size: data.len() as u64,
    })
}

fn write_json(path: &Path, value: &Value) -> Result<()> {
    let bytes = serde_json::to_vec_pretty(value)?;
    let temporary = path.with_extension("tmp");
    fs::write(&temporary, &bytes)?;
    fs::rename(&temporary, path)?;
    Ok(())
}

fn sandbox_config(
    tools: &Path,
    input: &Path,
    output: &Path,
    memory_mb: u32,
    entrypoint: SandboxEntrypoint,
    mappings: &[SandboxMapping],
) -> Result<String> {
    let tools = absolute(tools)?;
    let input = absolute(input)?;
    let output = absolute(output)?;
    for path in [&tools, &input, &output] {
        ensure!(
            !is_reparse_point(path),
            "sandbox mapping may not be a reparse point"
        );
    }
    let mut mapped_lines = String::new();
    for mapping in mappings {
        ensure!(
            mapping.host.is_absolute() && !is_reparse_point(&mapping.host),
            "runtime mapping host must be absolute and not a reparse point"
        );
        mapped_lines.push_str(&mapped_folder(
            &mapping.host,
            &mapping.guest,
            mapping.read_only,
        )?);
        mapped_lines.push('\n');
    }
    Ok(format!(
        r#"<?xml version="1.0" encoding="utf-8"?>
<Configuration>
  <Networking>Disable</Networking>
  <vGPU>Disable</vGPU>
  <ClipboardRedirection>Disable</ClipboardRedirection>
  <PrinterRedirection>Disable</PrinterRedirection>
  <AudioInputRedirection>Disable</AudioInputRedirection>
  <VideoInputRedirection>Disable</VideoInputRedirection>
  <ProtectedClient>Enable</ProtectedClient>
  <MemoryInMB>{memory_mb}</MemoryInMB>
  <MappedFolders>
{}
{}
{}
{mapped_lines}
  </MappedFolders>
  <LogonCommand>
    <Command>powershell.exe -NoProfile -ExecutionPolicy Bypass -File {}\{} -InputPath {} -OutputPath {}</Command>
  </LogonCommand>
</Configuration>
"#,
        mapped_folder(&tools, GUEST_TOOLS, true)?,
        mapped_folder(&input, GUEST_INPUT, true)?,
        mapped_folder(&output, GUEST_OUTPUT, false)?,
        xml_escape(GUEST_TOOLS),
        xml_escape(entrypoint.guest_script()),
        xml_escape(GUEST_INPUT),
        xml_escape(GUEST_OUTPUT),
    ))
}

fn mapped_folder(host: &Path, guest: &str, read_only: bool) -> Result<String> {
    let host = absolute(host)?;
    let host = host.to_string_lossy();
    ensure!(
        !host.contains(['\n', '\r']),
        "sandbox host path contains an unsupported character"
    );
    Ok(format!(
        "    <MappedFolder>\n      <HostFolder>{}</HostFolder>\n      <SandboxFolder>{}</SandboxFolder>\n      <ReadOnly>{}</ReadOnly>\n    </MappedFolder>",
        xml_escape(&host),
        xml_escape(guest),
        if read_only { "true" } else { "false" }
    ))
}

fn absolute(path: &Path) -> Result<PathBuf> {
    ensure!(
        path.is_absolute(),
        "sandbox path must be absolute: {path:?}"
    );
    Ok(path.to_path_buf())
}

fn relative_path(path: &str) -> Option<&str> {
    (path.len() <= 512
        && !path.contains(['\\', ':', '\0', '\n', '\r'])
        && path
            .split('/')
            .all(|part| !part.is_empty() && part != "." && part != ".."))
    .then_some(path)
}

fn is_identifier(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 128
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-' || byte == b'_')
}

fn is_sha256(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn xml_escape(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            '"' => escaped.push_str("&quot;"),
            '\'' => escaped.push_str("&apos;"),
            other => escaped.push(other),
        }
    }
    escaped
}

#[cfg(windows)]
fn is_reparse_point(path: &Path) -> bool {
    use std::os::windows::fs::MetadataExt;
    fs::symlink_metadata(path)
        .map(|metadata| metadata.file_attributes() & 0x400 != 0)
        .unwrap_or(false)
}

#[cfg(not(windows))]
fn is_reparse_point(_path: &Path) -> bool {
    false
}
